// ─── File: tests/advantages.spec.ts ───
import { test, expect } from '@playwright/test';

test.describe('Playwright advantages for a modern bank SPA', () => {

  // AUTO-WAITING: no sleeps; assertion retries until the SPA updates.
  test('auto-waiting handles async balance load', async ({ page }) => {
    await page.goto('/dashboard');
    // Balance loads asynchronously; web-first assertion waits automatically.
    await expect(page.getByTestId('account-balance')).toContainText('950,000');
  });

  // NETWORK MOCKING: test the UI deterministically without a live backend.
  test('mock the balance API to test UI states', async ({ page }) => {
    await page.route('**/api/v1/accounts/SAV2001/balance', async route => {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ accountId: 'SAV2001', balance: '1234567.00' }),
      });
    });
    await page.goto('/dashboard');
    await expect(page.getByTestId('account-balance')).toContainText('1,234,567');
  });

  // Simulate a backend ERROR deterministically (hard to do in Selenium).
  test('mock a 500 to assert graceful error UI', async ({ page }) => {
    await page.route('**/api/v1/accounts/**', route =>
      route.fulfill({ status: 500, body: 'boom' }));
    await page.goto('/dashboard');
    await expect(page.getByRole('alert'))
      .toHaveText(/unable to load your balance/i);
  });

  // ISOLATED CONTEXTS: two users in one test, independent sessions.
  test('isolated contexts for multi-user scenario', async ({ browser }) => {
    const rajesh = await browser.newContext();   // cheap, independent
    const priya = await browser.newContext();
    const p1 = await rajesh.newPage();
    const p2 = await priya.newPage();
    await p1.goto('/dashboard');
    await p2.goto('/dashboard');
    // Sessions do not leak state into each other.
    await rajesh.close();
    await priya.close();
  });
});
